<?php
declare(strict_types=1);require __DIR__.'/bootstrap.php';if(empty($_SESSION['admin_id'])){http_response_code(403);exit('Inhaberzugang erforderlich.');}require_once dirname(__DIR__).'/private/seo.php';require_once dirname(__DIR__).'/private/finance_export_service.php';
try{if(isset($_GET['template'])){$bytes=gszCsv(['punkt','breitengrad','laengengrad','position','wettbewerber','wettbewerber_position'],[]);$name='seo-vorlage.csv';}else{$keyword=filter_var($_GET['keyword']??0,FILTER_VALIDATE_INT);if(!$keyword||$keyword<1)throw new RuntimeException();$q=$pdo->prepare('SELECT k.keyword,k.location,r.measured_at,r.source,r.search_depth,p.point_key,p.latitude_e6,p.longitude_e6,p.rank_position,p.competitor,p.competitor_rank FROM seo_runs r JOIN seo_keywords k ON k.id=r.keyword_id JOIN seo_points p ON p.run_id=r.id WHERE r.keyword_id=? ORDER BY r.measured_at DESC,p.point_key LIMIT 10001');$q->execute([$keyword]);$rows=$q->fetchAll(PDO::FETCH_NUM);if(count($rows)>10000)throw new RuntimeException();foreach($rows as &$row){$row[6]=number_format($row[6]/1000000,6,'.','');$row[7]=number_format($row[7]/1000000,6,'.','');}unset($row);$bytes=gszCsv(['keyword','gebiet','messung_utc','quelle_nutzerangabe','messtiefe','punkt','breitengrad','laengengrad','position_0_nicht_gefunden','wettbewerber','wettbewerber_position'],$rows);$name='seo-messhistorie.csv';}header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="'.$name.'"');echo $bytes;}catch(Throwable $e){http_response_code(400);echo 'SEO-Export nicht verfügbar. Keyword/Migration/10000Zeilen-Limit prüfen.';}
